{
  "name": "neon-heist",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "NEON HEIST - an open-world crime action game for mobile and desktop browsers",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 5173",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^7.2.2"
  }
}

:root {
  --ink: #05070d;
  --panel: rgba(10, 15, 26, 0.92);
  --line: rgba(255, 255, 255, 0.12);
  --txt: #eef3ff;
  --muted: #8d9bb5;
  --neon: #43f0d0;
  --neon2: #ff3d81;
  --gold: #ffcb5c;
  --danger: #ff4d5e;
  --safe: env(safe-area-inset-bottom, 0px);
  --safeTop: env(safe-area-inset-top, 0px);
  --safeL: env(safe-area-inset-left, 0px);
  --safeR: env(safe-area-inset-right, 0px);
}
* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; height: 100%; overflow: hidden; background: var(--ink); color: var(--txt);
  font-family: Inter, system-ui, -apple-system, "Segoe UI", sans-serif; -webkit-user-select: none; user-select: none; }
#app { position: fixed; inset: 0; overflow: hidden; }
canvas#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
.hidden { display: none !important; }
.screen { position: absolute; inset: 0; z-index: 40; display: flex; align-items: center; justify-content: center; }
h1, h2, h3, .logo-mark, .logo-sub, .menu-btn, #missionHud, #weaponHud, #districtLabel, #bigMsg,
.kicker, #money, .tagline { font-family: "Barlow Condensed", Inter, sans-serif; }
.p { color: var(--muted); line-height: 1.55; font-size: 13px; }

/* LOADER */
#loader { background: radial-gradient(120% 90% at 50% 20%, #12203a 0%, #070b14 55%, #030509 100%); z-index: 100; }
.loader-inner { text-align: center; width: min(420px, 80vw); }
.logo-mark { font-size: 54px; letter-spacing: 6px; font-weight: 800; line-height: 1; }
.logo-mark span { color: var(--neon2); }
.logo-sub { font-size: 15px; letter-spacing: 14px; color: var(--neon); margin: 8px 0 34px; font-weight: 600; }
.bar { height: 3px; background: rgba(255,255,255,.1); overflow: hidden; }
#loadBar { height: 100%; width: 0%; background: linear-gradient(90deg, var(--neon), var(--neon2)); transition: width .25s; }
#loadText { margin-top: 14px; font-size: 11px; letter-spacing: 2px; color: var(--muted); text-transform: uppercase; }

/* MENU */
#menu { background: #060a12; flex-direction: column; justify-content: space-between; padding: 7vh 7vw; align-items: stretch; }
.menu-bg { position: absolute; inset: 0; background:
  linear-gradient(90deg, rgba(4,7,12,.94) 0%, rgba(4,7,12,.55) 48%, rgba(4,7,12,.15) 100%),
  radial-gradient(70% 80% at 78% 45%, rgba(255,61,129,.28), transparent 60%),
  radial-gradient(60% 60% at 55% 90%, rgba(67,240,208,.16), transparent 60%),
  linear-gradient(#0b1526, #05070d); }
.menu-bg:after { content:""; position:absolute; inset:0; background-image: linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.035) 1px, transparent 1px); background-size: 64px 64px; mask-image: radial-gradient(60% 60% at 60% 40%, #000, transparent); }
.menu-top { position: relative; display: flex; justify-content: space-between; gap: 30px; align-items: flex-end; flex: 1; }
.brand-kicker { font-size: 10px; letter-spacing: 4px; color: var(--neon); margin-bottom: 10px; }
.brand h1 { font-size: clamp(58px, 12vw, 138px); line-height: .82; margin: 0; font-weight: 800; letter-spacing: -2px; }
.brand h1 em { font-style: normal; color: transparent; -webkit-text-stroke: 2px var(--neon2); }
.tagline { color: var(--muted); font-size: 15px; letter-spacing: 2px; margin: 16px 0 0; }
.menu-actions { display: flex; flex-direction: column; gap: 8px; width: min(300px, 40vw); padding-bottom: 8px; }
.menu-btn { appearance: none; border: 1px solid var(--line); background: rgba(12,18,30,.72); color: var(--txt);
  font-size: 15px; letter-spacing: 2.5px; font-weight: 600; padding: 13px 20px; text-align: left; cursor: pointer;
  transition: .16s; backdrop-filter: blur(6px); }
.menu-btn:hover { border-color: var(--neon); background: rgba(67,240,208,.1); transform: translateX(4px); }
.menu-btn.primary { border-color: transparent; background: linear-gradient(90deg, var(--neon), #1fc9ae); color: #04110e; }
.menu-btn.primary:hover { filter: brightness(1.12); }
.menu-bottom { position: relative; display: flex; justify-content: space-between; align-items: center; border-top: 1px solid var(--line); padding-top: 16px; font-size: 10px; color: #64718a; letter-spacing: 1px; }
.save-meta { text-transform: uppercase; letter-spacing: 2px; }

/* PANELS */
.panel { width: min(560px, 90vw); background: var(--panel); border: 1px solid var(--line); padding: 22px; backdrop-filter: blur(20px); box-shadow: 0 30px 90px rgba(0,0,0,.6); max-height: 86vh; overflow: auto; }
.panel.wide { width: min(860px, 92vw); }
.panel-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }
.panel-head h2 { font-size: 26px; letter-spacing: 3px; margin: 0; font-weight: 700; }
.close { background: none; border: 1px solid var(--line); color: var(--txt); width: 34px; height: 34px; cursor: pointer; }
.close:hover { border-color: var(--neon2); color: var(--neon2); }
#codex, #settings, #pause, #result, #fail, #bigmap { background: rgba(3,6,11,.78); backdrop-filter: blur(6px); z-index: 60; }
.codex-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; }
.codex-grid h3 { font-size: 12px; letter-spacing: 2.5px; color: var(--neon); margin: 0 0 10px; }
.keys { list-style: none; margin: 0; padding: 0; font-size: 12px; color: var(--muted); line-height: 2.1; }
.keys b { display: inline-block; min-width: 82px; color: var(--txt); font-weight: 500; }
.settings-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 13px 0; border-bottom: 1px solid rgba(255,255,255,.06); font-size: 13px; }
.seg { display: flex; border: 1px solid var(--line); }
.seg button { background: none; border: 0; color: var(--muted); font: inherit; font-size: 10px; letter-spacing: 1px; padding: 7px 11px; cursor: pointer; }
.seg button.on { background: var(--neon); color: #04110e; font-weight: 700; }
input[type=range] { width: 140px; accent-color: var(--neon); }
input[type=checkbox] { width: 18px; height: 18px; accent-color: var(--neon); }
.settings-note { font-size: 11px; color: #61708c; margin-top: 14px; }
.pause-actions { display: flex; flex-direction: column; gap: 7px; }
.stats { margin-top: 16px; display: grid; grid-template-columns: 1fr 1fr; gap: 6px 20px; font-size: 11px; color: var(--muted); }
.stats b { color: var(--txt); float: right; }

/* HUD */
#hud { position: absolute; inset: 0; pointer-events: none; z-index: 20; }
#minimap { position: absolute; left: calc(14px + var(--safeL)); top: calc(14px + var(--safeTop)); width: 168px; height: 168px; border-radius: 50%;
  border: 2px solid rgba(255,255,255,.25); box-shadow: 0 4px 22px rgba(0,0,0,.6); pointer-events: auto; background: #0a1018; }
#districtLabel { position: absolute; left: 0; right: 0; top: calc(20px + var(--safeTop)); text-align: center; font-size: 13px; letter-spacing: 4px; color: rgba(255,255,255,.72); text-shadow: 0 2px 8px #000; }
#streetLabel { position: absolute; left: 0; right: 0; top: calc(38px + var(--safeTop)); text-align: center; font-size: 10px; letter-spacing: 2px; color: rgba(255,255,255,.35); }
#status { position: absolute; left: calc(16px + var(--safeL)); bottom: calc(18px + var(--safe)); display: flex; flex-direction: column; gap: 7px; }
.bars { display: flex; flex-direction: column; gap: 4px; }
.bar-wrap { width: 150px; height: 7px; background: rgba(0,0,0,.55); border: 1px solid rgba(255,255,255,.16); transform: skewX(-18deg); overflow: hidden; }
#healthBar { height: 100%; width: 100%; background: linear-gradient(90deg, #37e07f, #8ef5a9); transition: width .2s; }
#armorBar { height: 100%; width: 0%; background: linear-gradient(90deg, #4aa8ff, #9fd4ff); transition: width .2s; }
#money { font-size: 19px; letter-spacing: 1px; color: #c8ffe9; text-shadow: 0 2px 8px #000; }
#wanted { display: flex; gap: 2px; }
#wanted i { width: 16px; height: 16px; display: block; background: rgba(255,255,255,.14); clip-path: polygon(50% 0,61% 35%,98% 35%,68% 57%,79% 91%,50% 70%,21% 91%,32% 57%,2% 35%,39% 35%); }
#wanted i.on { background: var(--gold); filter: drop-shadow(0 0 4px rgba(255,203,92,.8)); animation: starpulse 1s infinite; }
@keyframes starpulse { 50% { opacity: .65; } }

#missionHud { position: absolute; right: calc(18px + var(--safeR)); top: calc(18px + var(--safeTop)); width: min(300px, 40vw); text-align: right; }
#missionTitle { font-size: 17px; letter-spacing: 2.5px; color: var(--gold); text-shadow: 0 2px 7px #000; }
#missionObjective { font-size: 12px; color: #dfe7f7; margin-top: 3px; text-shadow: 0 2px 6px #000; line-height: 1.4; }
#missionTimer { font-size: 15px; color: var(--txt); letter-spacing: 1px; margin-top: 4px; }
#missionProgress { height: 3px; background: rgba(0,0,0,.5); margin-top: 6px; margin-left: auto; width: 160px; }
#missionProgress span { display: block; height: 100%; width: 0%; background: var(--gold); transition: width .2s; }

#weaponHud { position: absolute; right: calc(20px + var(--safeR)); bottom: calc(18px + var(--safe)); text-align: right; }
#weaponName { font-size: 13px; letter-spacing: 2.5px; color: rgba(255,255,255,.7); }
#ammo { font-size: 30px; line-height: 1; letter-spacing: 1px; text-shadow: 0 2px 8px #000; }
#ammo span { font-size: 13px; color: var(--muted); }
#weaponSlots { display: flex; gap: 4px; justify-content: flex-end; margin-top: 7px; }
#weaponSlots i { width: 20px; height: 4px; background: rgba(255,255,255,.18); display: block; }
#weaponSlots i.on { background: var(--neon); }

#speedo { position: absolute; right: calc(20px + var(--safeR)); bottom: calc(18px + var(--safe)); text-align: right; }
.spd b { font-size: 38px; line-height: .9; font-family: "Barlow Condensed"; }
.spd span { font-size: 11px; color: var(--muted); margin-left: 5px; letter-spacing: 2px; }
#vehName { font-size: 11px; letter-spacing: 3px; color: var(--neon); margin-top: 2px; }
.damage { width: 120px; height: 3px; background: rgba(255,255,255,.15); margin: 7px 0 0 auto; }
#vehDamage { display: block; height: 100%; width: 100%; background: #ffd166; }
#interactPrompt { position: absolute; left: 50%; bottom: calc(24% + var(--safe)); transform: translateX(-50%); background: rgba(5,9,16,.72); border: 1px solid rgba(255,255,255,.16); padding: 8px 14px; font-size: 12px; display: flex; gap: 8px; align-items: center; backdrop-filter: blur(8px); }
#interactPrompt kbd { background: #fff; color: #05070d; font: 700 10px Inter; padding: 3px 6px; border-radius: 2px; }
#toast { position: absolute; left: 50%; top: calc(16% + var(--safeTop)); transform: translateX(-50%); background: rgba(5,9,16,.82); border-left: 3px solid var(--neon); padding: 9px 16px; font-size: 12px; letter-spacing: .6px; opacity: 0; transition: .3s; max-width: 70vw; text-align: center; backdrop-filter: blur(8px); }
#toast.show { opacity: 1; }
#subtitle { position: absolute; left: 50%; bottom: calc(15% + var(--safe)); transform: translateX(-50%); background: rgba(3,6,11,.82); padding: 10px 20px; max-width: min(760px, 84vw); text-align: center; border-left: 2px solid var(--neon2); backdrop-filter: blur(8px); }
#subtitle .who { display: block; font-size: 10px; letter-spacing: 2.5px; color: var(--neon); margin-bottom: 3px; text-transform: uppercase; }
#subtitle .line { font-size: 14px; line-height: 1.4; }
#bigMsg { position: absolute; left: 0; right: 0; top: 34%; text-align: center; font-size: clamp(34px, 7vw, 74px); letter-spacing: 8px; font-weight: 800; color: #fff; text-shadow: 0 6px 30px #000; opacity: 0; transition: opacity .5s, transform .5s; transform: scale(.96); }
#bigMsg.show { opacity: 1; transform: scale(1); }
#bigMsg em { color: var(--neon2); font-style: normal; }
#desktopHints { position: absolute; bottom: calc(12px + var(--safe)); left: 50%; transform: translateX(-50%); display: flex; gap: 14px; font-size: 9px; color: rgba(255,255,255,.28); letter-spacing: 1px; }
#desktopHints span { border: 1px solid rgba(255,255,255,.1); padding: 3px 6px; }
#fps { position: absolute; top: 6px; right: 8px; z-index: 50; font: 11px monospace; color: var(--neon); }

/* TOUCH */
#touch { position: absolute; inset: 0; display: none; pointer-events: none; }
body.touch #touch { display: block; }
#stickZone { position: absolute; left: calc(18px + var(--safeL)); bottom: calc(34px + var(--safe)); width: 148px; height: 148px; pointer-events: auto; touch-action: none; }
#stickBase { position: absolute; inset: 0; border-radius: 50%; border: 1.5px solid rgba(255,255,255,.18); background: rgba(8,12,20,.22); }
#stickKnob { position: absolute; left: 50%; top: 50%; width: 58px; height: 58px; margin: -29px 0 0 -29px; border-radius: 50%; background: rgba(255,255,255,.18); border: 1.5px solid rgba(255,255,255,.4); backdrop-filter: blur(3px); }
#touchLook { position: absolute; right: 0; top: 0; width: 55%; height: 100%; pointer-events: auto; touch-action: none; }
#touchButtons { position: absolute; inset: 0; pointer-events: none; }
.tbtn { position: absolute; pointer-events: auto; touch-action: none; border-radius: 50%; border: 1.5px solid rgba(255,255,255,.28); background: rgba(10,16,26,.4); color: #fff; font: 700 11px Inter; letter-spacing: 1px; backdrop-filter: blur(4px); }
.tbtn:active, .tbtn.down { background: rgba(67,240,208,.38); border-color: var(--neon); }
.tbtn.fire { right: calc(26px + var(--safeR)); bottom: calc(108px + var(--safe)); width: 84px; height: 84px; font-size: 12px; border-color: rgba(255,61,129,.6); background: rgba(255,61,129,.18); }
.tbtn.fire:active { background: rgba(255,61,129,.5); }
.tbtn.small { width: 56px; height: 56px; font-size: 9px; }
#tAim { right: calc(122px + var(--safeR)); bottom: calc(154px + var(--safe)); }
#tJump { right: calc(24px + var(--safeR)); bottom: calc(204px + var(--safe)); }
#tRun { left: calc(176px + var(--safeL)); bottom: calc(54px + var(--safe)); }
#tReload { right: calc(126px + var(--safeR)); bottom: calc(66px + var(--safe)); }
#tInteract { right: calc(64px + var(--safeR)); bottom: calc(36px + var(--safe)); width: 66px; height: 66px; background: rgba(67,240,208,.22); border-color: var(--neon); }
#tPhone { left: calc(18px + var(--safeL)); top: calc(196px + var(--safeTop)); width: 46px; height: 46px; }
#tPause { right: calc(18px + var(--safeR)); top: calc(14px + var(--safeTop)); width: 38px; height: 38px; border-radius: 6px; }

/* PHONE */
