184:     const mode = this.musicMode;
185:     if (mode === 'paused') return;
186:     const bar = Math.floor(step / 16);
187:     const s = step % 16;
188:     // chords: Am F C G, in A minor-ish synthwave
189:     const roots = [55, 43.65, 65.4, 49];
190:     const chord = [[220, 261.6, 329.6], [174.6, 220, 261.6], [196, 246.9, 329.6], [196, 246.9, 293.7]][bar];
191:     const busy = mode === 'combat';
192:     const density = mode === 'menu' ? 0.7 : 1;
193: 
194:     // bass pulse 8ths
195:     if (s % 2 === 0) this.mnote(roots[bar] * (s % 4 === 2 ? 2 : 1), t, sd * 1.6, 'sawtooth', 0.1 * density, 260);
196:     // kick
197:     if (s % 4 === 0) this.kick(t, 0.25 * density);
198:     // snare
199:     if (s % 8 === 4) this.snare(t, 0.1 * density);
200:     // hats
201:     if (s % 2 === 1 && busy) this.hat(t, 0.035);
202:     // arp
203:     if (s % 2 === 0 && (s % 4 === 0 || busy || mode === 'menu')) {
204:       const n = chord[(s / 2) % 3] * (s % 8 === 0 ? 2 : 1);
205:       this.mnote(n, t, sd * 1.1, 'triangle', 0.035 * density, 3200);
206:     }
207:     // pad at bar start
208:     if (s === 0) {
209:       chord.forEach((n, i) => this.mnote(n * 0.5, t, sd * 14, 'sine', 0.028, 1200 + i * 200));
210:     }
211:     // lead motif every other bar
212:     if (busy && s === 8) this.mnote(chord[2] * 2, t, sd * 2, 'square', 0.03, 2600);
213:   }
