function save(){writeSave({...state,player:{x:player.x,z:player.z,yaw:player.yaw},missionIndex:missions.index,done:missions.done});toast('Progress saved to this device.');}
function restore(){const s=loadSave();if(!s)return false;Object.assign(state,s);player.x=s.player?.x??0;player.z=s.player?.z??13;player.yaw=s.player?.yaw??0;missions.index=s.missionIndex||0;missions.done=s.done||0;return true;}
function startGame(continuing=false){audio.resume();if(continuing)restore();else{clearSave();Object.assign(state,{money:2400,health:100,armor:35,wanted:0,heat:0,kills:0,played:0,weapon:0});missions.index=0;missions.done=0;player.x=0;player.z=13;player.yaw=0;}playing=true;paused=false;screen(null);hide('menu');hide('loader');show('hud');input.enabled=true;audio.musicMode='city';toast(continuing?'Welcome back to Viceport.':'Sable is waiting by the marina. Find the gold marker.');refreshPhone();}
