28:function save(){writeSave({...state,player:{x:player.x,z:player.z,yaw:player.yaw},missionIndex:missions.index,done:missions.done});toast('Progress saved to this device.');}
30:function startGame(continuing=false){audio.resume();if(continuing)restore();else{clearSave();Object.assign(state,{money:2400,health:100,armor:35,wanted:0,heat:0,kills:0,played:0,weapon:0});missions.index=0;missions.done=0;player.x=0;player.z=13;player.yaw=0;}playing=true;paused=false;screen(null);hide('menu');hide('loader');show('hud');input.enabled=true;audio.musicMode='city';toast(continuing?'Welcome back to Viceport.':'Sable is waiting by the marina. Find the gold marker.');refreshPhone();}
31:function pause(){if(!playing||phoneOpen)return;paused=!paused;input.enabled=!paused;audio.musicMode=paused?'paused':state.wanted?'combat':'city';if(paused){show('pause');$('pauseStats').innerHTML=`Jobs completed <b>${missions.done}</b><br>Cash earned <b>${formatMoney(state.money)}</b><br>People stopped <b>${state.kills}</b><br>Districts explored <b>12</b>`;}else hide('pause');}
32:input.on('pause',pause);input.on('phone',togglePhone);input.on('map',()=>{if(playing&&!paused){drawMaps();show('bigmap');paused=true;input.enabled=false;}});input.on('weapon',i=>{if(i<weapons.length){state.weapon=i;updateWeapon();}});input.on('vehicle',enterVehicle);input.on('horn',()=>{if(player.vehicle){audio.horn();toast('HONK');}});input.on('crouch',()=>{player.crouch=!player.crouch;toast(player.crouch?'Crouched':'Standing');});input.on('lock',locked=>{if(locked)audio.resume();});
33:function closeMap(){hide('bigmap');paused=false;input.enabled=true;}
36:function nearestVehicle(){let best=null,bd=6;for(const v of world.vehicles){if(v.occupied)continue;const d=dist(player.x,player.z,v.x,v.z);if(d<bd){bd=d;best=v;}}return best;}
37:function enterVehicle(){if(player.vehicle){const v=player.vehicle;v.occupied=false;player.vehicle=null;player.x=v.x+Math.sin(v.yaw+1.5)*2;player.z=v.z+Math.cos(v.yaw+1.5)*2;hero.visible=true;toast('You left the vehicle.');audio.crash(.3);return;}const v=nearestVehicle();if(!v){toast('No vehicle close enough.');return;}if(v.police){raiseWanted(1);toast('You commandeered a VCPD cruiser!');}player.vehicle=v;v.occupied=true;hero.visible=false;toast(`${v.name} — drive clear.`);audio.pickup();}
38:function raiseWanted(n=1){state.heat=clamp(state.heat+n,0,10);state.wanted=clamp(Math.ceil(state.heat/2),1,5);audio.siren(state.wanted,true);for(const p of world.people)if(dist(p.x,p.z,player.x,player.z)<55)p.panic=6;}
