 const mode=player.vehicle?'DRIVE':state.weapon===7?'UNARMED':`WEAPON ${state.weapon+1}`;$('weaponSlots').innerHTML=weapons.slice(0,8).map((a,i)=>`<span class="${i===state.weapon?'on':''}">${i+1}</span>`).join('');setDistrict();clockTotal+=dt;state.played+=dt;state.clock=(state.clock+dt*.025)%24;refreshPhone();drawMap($('minimap'));if(settings.fps){const fps=dt?Math.round(1/dt):60;$('fps').textContent=`${fps} FPS`;}}

