10:     this.materials={road:mat('#202a35'),side:mat('#a3a99b'),grass:mat('#25483d'),water:mat('#126078',.25,{metalness:.2}),building: ['#334452','#4b4c58','#615248','#3c5a5a','#555c70'].map(c=>mat(c)),window:mat('#50d9d4',.28,{emissive:'#145b60',emissiveIntensity:.35}),white:mat('#ded8c4'),yellow:mat('#dfb74c'),red:mat('#d55b53'),blue:mat('#4b9cbb'),black:mat('#161c25'),leaf:mat('#28715c'),trunk:mat('#604a38')};
11:     this.makeGround(); this.makeCity(); this.makeLandmarks(); this.makeVehicles(); this.makePeople(); this.makeLights();
12:   }
13:   add(mesh,x,y,z,group=this.scene){mesh.position.set(x,y,z);group.add(mesh);return mesh;}
14:   makeGround(){const g=box(500,.4,500,this.materials.grass);this.add(g,0,-.3,0);const sea=box(500,.2,85,this.materials.water);this.add(sea,0,-.08,-205);}
15:   makeCity(){
16:     // Seamless 1.2 km city grid; broad avenues, neighborhood blocks and coastal promenade.
17:     const roadMat=this.materials.road, sidewalk=this.materials.side;
18:     for(let i=-5;i<=5;i++){
19:       const p=i*38; let r=box(9,.08,420,roadMat);this.add(r,p,.01,0);let r2=box(420,.08,9,roadMat);this.add(r2,0,.012,p);
20:       for(const s of [-1,1]){this.add(box(1,.15,420,sidewalk),p+s*5,.07,0);this.add(box(420,.15,1,sidewalk),0,.07,p+s*5);}
21:       if(i>-5&&i<5) for(let j=-5;j<5;j++){
22:         const x=p+19,z=j*38+19, rng=this.rng, district=(Math.abs(x)<60&&Math.abs(z)<60)?'core':Math.abs(z)>140?'coast':Math.abs(x)>115?'residential':'mixed';
23:         const count=district==='core'?4:2;
24:         for(let k=0;k<count;k++){
25:           const bx=x+rng.range(-12,12),bz=z+rng.range(-12,12),w=rng.range(7,13),d=rng.range(7,13);
26:           const h=district==='core'?rng.range(24,78):district==='mixed'?rng.range(10,32):rng.range(7,18);
27:           const b=box(w,h,d,rng.pick(this.materials.building));this.add(b,bx,h/2,bz);this.colliders.push({x:bx,z:bz,w,d,h});
28:           for(let yy=3;yy<h-1;yy+=4){const strip=box(w*.78,.35,.08,this.materials.window);this.add(strip,bx,yy,bz+d/2+.05);const strip2=box(.08,.35,d*.75,this.materials.window);this.add(strip2,bx+w/2+.05,yy,bz);}
29:           const roof=box(w*.25,1,d*.22,this.materials.black);this.add(roof,bx,h+.5,bz);
30:         }
31:         if(rng.f()<.42) this.makeTree(x+rng.range(-13,13),z+rng.range(-13,13));
32:       }
33:     }
34:     // Beach + promenade and park islands
35:     for(let i=0;i<30;i++){const x=-190+i*13;const sand=box(12,.16,25,mat('#c5a978'));this.add(sand,x,-.05,-178);this.makeTree(x+4,-166);}
36:   }
37:   makeTree(x,z){const t=new THREE.Group();t.add(box(.8,4,.8,this.materials.trunk));const crown=new THREE.Mesh(new THREE.SphereGeometry(2.4,7,6),this.materials.leaf);crown.position.y=3.5;t.add(crown);this.add(t,x,1.8,z);}
38:   makeLandmarks(){
39:     const mark=(name,x,z,color)=>{let g=new THREE.Group();const base=new THREE.Mesh(new THREE.CylinderGeometry(1.3,1.3,.4,16),mat(color,.3,{emissive:color,emissiveIntensity:.8}));base.position.y=.2;g.add(base);const beam=new THREE.Mesh(new THREE.CylinderGeometry(.08,.08,8,8),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.2}));beam.position.y=4;g.add(beam);g.position.set(x,.2,z);this.scene.add(g);this.markers.push({name,x,z,obj:g});};
40:     const labels=[['SABLE · FIRST CONTACT',8,6,'#ffcb5c'],['MAMA C · LITTLE HAVANA',-114,76,'#43f0d0'],['WRENCH · IRONWORKS',130,0,'#ff3d81'],['SAFEHOUSE · SOLANO',-76,-114,'#64ff9b'],['DOCKS · JOB BOARD',-76,152,'#ffc857'],['AIRFIELD · KINSPORT',152,-152,'#b49cff']];labels.forEach(a=>mark(...a));
41:     // skyline landmark: port tower and lit sign
42:     const tower=box(18,96,18,mat('#243443'));this.add(tower,0,48,0);const beacon=box(19,1,19,mat('#46d9d1',.3,{emissive:'#46d9d1',emissiveIntensity:2}));this.add(beacon,0,96,0);
43:   }
44:   makeCar(x,z,color,police=false){const g=new THREE.Group();const body=box(2.2,.72,4,mat(color,.4,{metalness:.3}));body.position.y=.75;g.add(body);const cab=box(1.65,.7,1.8,mat(police?'#b8c5cb':'#18232b',.25,{metalness:.2}));cab.position.set(0,1.38,-.1);g.add(cab);
45:     for(const xx of [-1,1])for(const zz of [-1.25,1.25]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.38,.38,.22,10),mat('#11151a'));wheel.rotation.z=Math.PI/2;wheel.position.set(xx, .4, zz);g.add(wheel);}
