48:   }
49:   makeVehicles(){for(let i=0;i<40;i++){const road=this.rng.int(-5,5)*38, cross=this.rng.range(-180,180);const vertical=this.rng.f()>.5;const v=this.makeCar(vertical?road:cross,vertical?cross:road,this.rng.pick(['#e4e6d9','#c04b57','#d0a63e','#387d9a','#333d49']));v.yaw=vertical?0:Math.PI/2;v.obj.rotation.y=v.yaw;v.speed=this.rng.range(2,5);} for(let i=0;i<3;i++){const v=this.makeCar(-150+i*12,130,'#dedede',true);v.yaw=Math.PI/2;v.obj.rotation.y=v.yaw;}}
50:   makePerson(x,z){const g=new THREE.Group();const body=box(.55,1,.35,mat(pick(['#e95770','#e8c85b','#62c3aa','#5779d5','#d7d9de'])));body.position.y=1.1;g.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.24,8,6),mat('#bd8d69'));head.position.y=1.78;g.add(head);this.scene.add(g);this.people.push({obj:g,x,z,dir:rand(0,Math.PI*2),speed:rand(.4,1),panic:0});}
51:   makePeople(){for(let i=0;i<55;i++){const x=rand(-180,180),z=rand(-180,180);if(Math.abs(x%38)<7||Math.abs(z%38)<7)this.makePerson(x,z);}}
