// Vehicle and combat interactions
function nearestVehicle(){let best=null,bd=6;for(const v of world.vehicles){if(v.occupied)continue;const d=dist(player.x,player.z,v.x,v.z);if(d<bd){bd=d;best=v;}}return best;}
function enterVehicle(){if(player.vehicle){const v=player.vehicle;v.occupied=false;player.vehicle=null;player.x=v.x+Math.sin(v.yaw+1.5)*2;player.z=v.z+Math.cos(v.yaw+1.5)*2;hero.visible=true;toast('You left the vehicle.');audio.crash(.3);return;}const v=nearestVehicle();if(!v){toast('No vehicle close enough.');return;}if(v.police){raiseWanted(1);toast('You commandeered a VCPD cruiser!');}player.vehicle=v;v.occupied=true;hero.visible=false;toast(`${v.name} — drive clear.`);audio.pickup();}
function raiseWanted(n=1){state.heat=clamp(state.heat+n,0,10);state.wanted=clamp(Math.ceil(state.heat/2),1,5);audio.siren(state.wanted,true);for(const p of world.people)if(dist(p.x,p.z,player.x,player.z)<55)p.panic=6;}
function fire(){if(!playing||paused||phoneOpen||player.fireCooldown>0)return;const w=weapons[state.weapon];if(state.weapon===7){audio.gunshot('melee');state.fireCooldown=.45;let target=nearestPerson(3);if(target){damageTarget(target,45);return;}return;}if(state.ammo[state.weapon]<=0){toast('Empty — reload with R.');audio.click();player.fireCooldown=.3;return;}state.ammo[state.weapon]--;player.fireCooldown=state.weapon===3?.13:.3;audio.gunshot(w[2]);state.heat+=state.weapon===6?3:.35;
 const origin=new THREE.Vector3(player.x,player.vehicle?1.4:1.55,player.z),dir=new THREE.Vector3(Math.sin(player.yaw),0,Math.cos(player.yaw));let target=null,best=state.weapon===4?110:48;
 const targets=[...world.people.map(p=>({type:'person',o:p})),...police.map(p=>({type:'police',o:p}))];for(const t of targets){const o=t.o,dx=o.x-player.x,dz=o.z-player.z,d=Math.hypot(dx,dz);if(d>best||d<.1)continue;const dot=(dx*dir.x+dz*dir.z)/d;if(dot>.93){best=d;target=t;}}
 const mesh=new THREE.Mesh(dotGeo,bulletMat);mesh.position.copy(origin).addScaledVector(dir,1);scene.add(mesh);bullets.push({mesh,dir,life:.17});if(target)damageTarget(target,state.weapon===1?90:state.weapon===4?130:55);else raiseWanted(state.weapon===6?2:1);
}
function nearestPerson(max=99){let b=null,bd=max;for(const p of world.people){const d=dist(player.x,player.z,p.x,p.z);if(d<bd){b={type:'person',o:p};bd=d;}}return b;}
function damageTarget(t,n){if(t.type==='person'){const i=world.people.indexOf(t.o);if(i>=0){scene.remove(t.o.obj);world.people.splice(i,1);state.kills++;world.makePerson(rand(-170,170),rand(-170,170));}}else{t.o.health-=n;if(t.o.health<=0){scene.remove(t.o.obj);police=police.filter(p=>p!==t.o);}}raiseWanted(1);}
function reload(){const i=state.weapon;if(i>5)return;const need=weapons[i][1]-state.ammo[i],take=Math.min(need,state.reserve[i]);if(take<=0){toast('No reserve ammunition. Visit a gun shop.');return;}state.ammo[i]+=take;state.reserve[i]-=take;audio.click();updateWeapon();}

// Law response, mission markers and city map
let police=[];let policeSpawn=0,heatQuiet=0;
function spawnPolice(){if(police.length>=Math.min(2+state.wanted*2,10))return;const a=rand(0,Math.PI*2),d=rand(45,70),v=world.makeCar(player.x+Math.sin(a)*d,player.z+Math.cos(a)*d,'#d7e1e6',true);v.speed=0;v.health=100;police.push(v);}
function markerForMission(){for(const m of world.markers)m.obj.visible=false;if(missions.active){const [x,z]=missions.active.spots[missions.stage];let m=world.markers[0];m.x=x;m.z=z;m.name=missions.active.arc[missions.stage];m.obj.position.set(x,.2,z);m.obj.visible=true;}else{const m=world.markers[0];m.x=8;m.z=6;m.name='SABLE · FIRST CONTACT';m.obj.position.set(8,.2,6);m.obj.visible=true;}}
function drawMap(canvas,large=false){const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.clearRect(0,0,w,h);c.fillStyle='#101c27';c.fillRect(0,0,w,h);const span=large?1240:300,scale=Math.min(w,h)/span,ox=w/2-player.x*scale,oy=h/2-player.z*scale;
 c.fillStyle='#125366';c.fillRect(0,oy-720*scale,w,165*scale);c.fillStyle='#c2a776';c.fillRect(ox-600*scale,oy-555*scale,1200*scale,12*scale);
 c.fillStyle='#4b6372';for(let x=-560;x<600;x+=75)for(let z=-560;z<600;z+=75)c.fillRect(ox+(x+12)*scale,oy+(z+12)*scale,49*scale,49*scale);
 c.strokeStyle='#364757';c.lineWidth=Math.max(1.5,9*scale);for(let q=-600;q<=600;q+=75){c.beginPath();c.moveTo(ox+q*scale,oy-600*scale);c.lineTo(ox+q*scale,oy+600*scale);c.stroke();c.beginPath();c.moveTo(ox-600*scale,oy+q*scale);c.lineTo(ox+600*scale,oy+q*scale);c.stroke();}
 world.markers.filter(m=>m.obj.visible).forEach(m=>{c.fillStyle='#ffcb5c';c.beginPath();c.arc(ox+m.x*scale,oy+m.z*scale,large?7:4,0,7);c.fill();});c.fillStyle='#48f5e1';c.beginPath();c.arc(w/2,h/2,large?6:4,0,7);c.fill();c.strokeStyle='#48f5e1';c.beginPath();c.moveTo(w/2,h/2);c.lineTo(w/2+Math.sin(player.yaw)*14,h/2+Math.cos(player.yaw)*14);c.stroke();}
function drawMaps(){drawMap($('minimap'));drawMap($('phoneMap'),true);drawMap($('bigmapCanvas'),true);}

