function togglePhone(){if(!playing||paused&&!phoneOpen)return;if(phoneOpen){phoneOpen=false;hide('phone');paused=false;input.enabled=true;return;}phoneOpen=true;paused=true;input.enabled=false;hide('pause');show('phone');openPhoneApp('home');refreshPhone();}
function openPhoneApp(name){document.querySelectorAll('.phone-app').forEach(e=>e.classList.remove('active'));const el=$(`phoneApp${name[0].toUpperCase()+name.slice(1)}`);if(el)el.classList.add('active');if(name==='map')drawMaps();if(name==='missions')renderJobs();if(name==='shop')renderShop();if(name==='garage')renderGarage();}
function refreshPhone(){$('phoneMoney').textContent=formatMoney(state.money);$('shopMoney').textContent=formatMoney(state.money);$('phoneObjective').textContent=missions.active?`${missions.active.title}: ${missions.active.arc[missions.stage]}`:`Available: ${missions.next.title} · ${missions.next.kind}`;$('phoneTime').textContent=`${String(Math.floor(state.clock)%24).padStart(2,'0')}:${String(Math.floor((state.clock%1)*60)).padStart(2,'0')}`;}
function renderJobs(){const root=$('jobsList');root.innerHTML='';const current=missions.active?.id??missions.index;MISSIONS.slice(Math.max(0,current-1),Math.min(MISSIONS.length,current+5)).forEach(m=>{const row=document.createElement('button');row.className='phone-row';row.innerHTML=`<b>${String(m.id+1).padStart(2,'0')} · ${m.title}</b><span>${m.kind} · ${formatMoney(m.pay)}${m.id<missions.index?' · COMPLETE':''}</span>`;row.disabled=!!missions.active||m.id>missions.index;row.addEventListener('click',()=>{if(missions.start(m.id)){markerForMission();toast(`JOB ACCEPTED · ${m.title}`);audio.success();refreshPhone();}});root.appendChild(row);});}
const shopItems=[{name:'First aid kit',desc:'Restore 45 health',cost:180,act:()=>state.health=Math.min(100,state.health+45)},{name:'Armor vest',desc:'Restore 35 armor',cost:320,act:()=>state.armor=Math.min(100,state.armor+35)},{name:'Pistol ammunition',desc:'+36 rounds',cost:240,act:()=>state.reserve[0]+=36},{name:'Rifle ammunition',desc:'+90 rounds',cost:520,act:()=>state.reserve[2]+=90},{name:'Safehouse · Solano',desc:'Save point + free recovery',cost:3200,act:()=>{state.property=true;state.health=100;state.armor=100;}},{name:'Calypso GT',desc:'Personal car · delivered nearby',cost:5400,act:()=>{state.ownedCars.push('Calypso GT');const v=world.makeCar(player.x+4,player.z+4,'#25cbbd');v.name='Calypso GT';}}];
function renderShop(){const root=$('shopList');root.innerHTML='';for(const item of shopItems){const row=document.createElement('button');row.className='phone-row';row.innerHTML=`<b>${item.name} <i>${formatMoney(item.cost)}</i></b><span>${item.desc}</span>`;row.disabled=state.money<item.cost||(item.name.startsWith('Safehouse')&&state.property);row.addEventListener('click',()=>{if(state.money<item.cost)return;state.money-=item.cost;item.act();audio.pickup();toast(`${item.name} purchased.`);renderShop();refreshPhone();});root.appendChild(row);}}
function renderGarage(){const root=$('garageList');root.innerHTML='';const row=document.createElement('button');row.className='phone-row';row.innerHTML='<b>Request vehicle</b><span>Deliver a car to your location · $150</span>';row.disabled=state.money<150||!state.ownedCars.length;row.addEventListener('click',()=>{if(!state.ownedCars.length){toast('Buy a personal car in the shop first.');return;}state.money-=150;const v=world.makeCar(player.x+Math.sin(player.yaw+1)*5,player.z+Math.cos(player.yaw+1)*5,'#25cbbd');v.name=state.ownedCars[0];audio.pickup();refreshPhone();renderGarage();});root.appendChild(row);const note=document.createElement('div');note.className='phone-note';note.textContent=state.ownedCars.length?`Owned: ${state.ownedCars.join(', ')}`:'No personal vehicles yet.';root.appendChild(note);}

