$('btnResume').addEventListener('click',pause);$('btnResume2').addEventListener('click',pause);$('btnSave').addEventListener('click',save);$('btnQuit').addEventListener('click',goMenu);$('btnPauseSettings').addEventListener('click',()=>show('settings'));$('resultBtn').addEventListener('click',()=>{hide('result');paused=false;input.enabled=true;refreshPhone();});$('failRetry').addEventListener('click',()=>{state.health=100;state.armor=Math.max(20,state.armor);player.x=0;player.z=13;missions.abandon();hide('fail');paused=false;input.enabled=true;toast('Recovered at Solano. Accept the job again on your phone.');});$('failQuit').addEventListener('click',()=>{hide('fail');goMenu();});
function applySettings(){settings.music=Number($('musicVol').value);settings.sfx=Number($('sfxVol').value);settings.invert=$('invertY').checked;settings.fps=$('showFps').checked;audio.setVolumes(settings.music,settings.sfx);saveSettings(settings);$('fps').classList.toggle('hidden',!settings.fps);}
